// Battery dimensions: 56mm x 36mm x 13mm
// Arrangement: 4x1 linear, batteries upright on smallest face (13x36)
// Batteries face each other with largest face (56x36)

// Battery dimensions
bat_length = 56;  // height when upright
bat_width = 36;   // depth
bat_thickness = 13;  // side-to-side when arranged

// Tolerances and wall parameters
tolerance = 0.5;  // clearance around battery
wall = 2.5;       // wall thickness
base_height = 3;  // bottom thickness
snap_height = 5;  // height of snap-fit tab
snap_depth = 1.2; // how far snap protrudes into slot
snap_width = 10;  // width of snap tab

// Finger hole parameters
finger_hole_diameter = 20;
finger_hole_height = 15;

// Slot dimensions (with tolerance)
slot_length = bat_length + tolerance;  // Z height
slot_width = bat_width + tolerance;    // Y depth
slot_thickness = bat_thickness + tolerance;  // X width

// Number of batteries
num_batteries = 4;

// Overall case dimensions
case_width = num_batteries * slot_thickness + (num_batteries + 1) * wall;
case_depth = slot_width + 2 * wall;
case_height = slot_length + base_height;

// Main module
module battery_case() {
    difference() {
        // Outer shell
        outer_shell();

        // Battery slots
        for (i = [0:num_batteries-1]) {
            translate([wall + i * (slot_thickness + wall), wall, base_height])
                battery_slot();
        }

        // Finger holes from bottom
        for (i = [0:num_batteries-1]) {
            slot_center_x = wall + i * (slot_thickness + wall) + slot_thickness/2;
            translate([slot_center_x, wall + slot_width/2, -0.1])
                finger_hole();
        }
    }

    // Add snap-fit tabs
    for (i = [0:num_batteries-1]) {
        slot_x = wall + i * (slot_thickness + wall);
        // Left side snap
        translate([slot_x, wall + slot_width/2, base_height + slot_length - snap_height - 10])
            snap_tab();
        // Right side snap
        translate([slot_x + slot_thickness, wall + slot_width/2, base_height + slot_length - snap_height - 10])
            mirror([1, 0, 0]) snap_tab();
    }
}

module outer_shell() {
    // Rounded outer shell for better printability
    hull() {
        r = 3;
        translate([r, r, 0])
            cylinder(r=r, h=case_height, $fn=32);
        translate([case_width - r, r, 0])
            cylinder(r=r, h=case_height, $fn=32);
        translate([r, case_depth - r, 0])
            cylinder(r=r, h=case_height, $fn=32);
        translate([case_width - r, case_depth - r, 0])
            cylinder(r=r, h=case_height, $fn=32);
    }
}

module battery_slot() {
    // Main slot cavity
    cube([slot_thickness, slot_width, slot_length + 1]);
}

module finger_hole() {
    // Oval/elongated hole for finger access
    hull() {
        cylinder(d=finger_hole_diameter, h=base_height + finger_hole_height + 0.2, $fn=48);
    }
    // Taper at bottom for easier printing (chamfer)
    translate([0, 0, -0.1])
        cylinder(d1=finger_hole_diameter + 4, d2=finger_hole_diameter, h=2, $fn=48);
}

module snap_tab() {
    // Flexible snap tab that protrudes into slot
    // Angled design for easy insertion and retention

    tab_base_width = snap_width;
    tab_height = snap_height;

    translate([0, -tab_base_width/2, 0]) {
        difference() {
            union() {
                // Main flexible arm
                cube([wall + snap_depth, tab_base_width, tab_height]);

                // Snap bump (ramped for insertion, vertical for retention)
                translate([wall, 0, tab_height * 0.3])
                    snap_bump();
            }

            // Cut relief slot for flexibility
            translate([wall * 0.3, tab_base_width/2 - 0.4, -0.1])
                cube([wall + snap_depth + 1, 0.8, tab_height * 0.7]);
        }
    }
}

module snap_bump() {
    // The actual snap protrusion - ramped entry, steeper exit
    bump_height = snap_height * 0.5;

    // Angled bump for snap fit
    hull() {
        cube([0.1, snap_width, bump_height]);
        translate([snap_depth, 0, bump_height * 0.3])
            cube([0.1, snap_width, bump_height * 0.4]);
    }
}

// Render the case
battery_case();
