snap_depth = 1.5; // how far snap protrudes into slot
snap_width = 12;  // width of snap tab
snap_position = 0.7; // position from bottom (0-1)

// Finger hole parameters
finger_hole_diameter = 18;

// Slot dimensions (with tolerance)
slot_length = bat_length + tolerance;  // Z height
slot_width = bat_width + tolerance;    // Y depth
slot_thickness = bat_thickness + tolerance;  // X width

// Number of batteries
num_batteries = 4;

// Overall case dimensions
case_width = num_batteries * slot_thickness + 2 * wall + (num_batteries - 1) * divider_wall;
case_depth = slot_width + 2 * wall;
case_height = slot_length + base_height;

$fn = 48;

// Main module
module battery_case() {
    difference() {
        union() {
            // Outer shell
            outer_shell();

            // Add snap-fit tabs on front and back walls
            for (i = [0:num_batteries-1]) {
                slot_center_x = get_slot_x(i) + slot_thickness/2;

                // Front wall snaps
                translate([slot_center_x, wall, base_height + slot_length * snap_position])
                    rotate([0, 0, 180])
                        snap_tab();

                // Back wall snaps
                translate([slot_center_x, case_depth - wall, base_height + slot_length * snap_position])
                    snap_tab();
            }
        }

        // Battery slots
        for (i = [0:num_batteries-1]) {
            translate([get_slot_x(i), wall, base_height])
                battery_slot();
        }

        // Finger holes from bottom
        for (i = [0:num_batteries-1]) {
            slot_center_x = get_slot_x(i) + slot_thickness/2;
            translate([slot_center_x, wall + slot_width/2, -0.1])
                finger_hole();
        }

        // Chamfer top edges for comfort
        translate([0, 0, case_height])
            top_chamfer();
