function get_slot_x(i) = wall + i * (slot_thickness + divider_wall);

module outer_shell() {
    // Rounded outer shell for better printability and aesthetics
    r = 3;
    linear_extrude(height = case_height) {
        hull() {
            translate([r, r])
                circle(r=r);
            translate([case_width - r, r])
                circle(r=r);
            translate([r, case_depth - r])
                circle(r=r);
            translate([case_width - r, case_depth - r])
                circle(r=r);
