module finger_hole() {
    // Hole for finger access to push battery out
    cylinder(d=finger_hole_diameter, h=base_height + 0.2);

    // Chamfer at bottom for cleaner print
    translate([0, 0, -0.1])
        cylinder(d1=finger_hole_diameter + 3, d2=finger_hole_diameter, h=1.5);

    // Chamfer at top (inside slot) for finger comfort
    translate([0, 0, base_height - 1])
        cylinder(d1=finger_hole_diameter, d2=finger_hole_diameter + 4, h=3);
}

module snap_tab() {
