            relief_width = 2;
            translate([snap_width * 0.25 - relief_width/2, 0.5, -0.1])
                cube([relief_width, arm_length - 1, tab_thickness + 0.2]);
            translate([snap_width * 0.75 - relief_width/2, 0.5, -0.1])
                cube([relief_width, arm_length - 1, tab_thickness + 0.2]);
