module battery_case() {
    difference() {
        // Solid outer shell with integrated snaps
        outer_shell_with_snaps();

        // Battery slots (cut out)
        for (i = [0:num_batteries-1]) {
            translate([get_slot_x(i), wall, base_height])
                battery_slot();
        }

        // Finger holes from bottom
        for (i = [0:num_batteries-1]) {
            slot_center_x = get_slot_x(i) + slot_thickness/2;
            translate([slot_center_x, wall + slot_width/2, -0.1])
                finger_hole();
        }
    }
}

module outer_shell_with_snaps() {
    r = 3;

    // Main body
    linear_extrude(height = case_height) {
        hull() {
            translate([r, r]) circle(r=r);
            translate([case_width - r, r]) circle(r=r);
            translate([r, case_depth - r]) circle(r=r);
            translate([case_width - r, case_depth - r]) circle(r=r);
        }
    }

    // Add snap bumps inside each slot (on front and back walls)
    snap_z = base_height + slot_length - 15; // Position near top

    for (i = [0:num_batteries-1]) {
        slot_center_x = get_slot_x(i) + slot_thickness/2;

        // Front wall snap (faces +Y direction, into slot)
        translate([slot_center_x, wall, snap_z])
            rotate([0, 0, 0])
                snap_ridge();

        // Back wall snap (faces -Y direction, into slot)
        translate([slot_center_x, case_depth - wall, snap_z])
            rotate([0, 0, 180])
                snap_ridge();
    }
}

module snap_ridge() {
