    // Ramped top for easy insertion, sharper bottom edge for retention

    ridge_height = 8;

    translate([-snap_width/2, 0, 0]) {
        // Main ridge - triangular cross-section
        linear_extrude(height = snap_width) {
            polygon([
                [0, 0],                          // base at wall
                [0, snap_protrusion],            // tip of ridge
                [snap_ramp, 0],                  // top ramp (easy insert)
            ]);
        }

        // Lower retention lip (steeper)
        translate([0, 0, 0])
        linear_extrude(height = snap_width) {
            polygon([
                [0, 0],
                [0, snap_protrusion],
                [-1.5, 0],  // small undercut for retention
